/** ⇒ { kv, userSets, ended } */
function endEverywhere(kv, userSets, userId) {
  // Write your solution here
  var ended = 0;
  Object.keys(kv).forEach(function (k) { if (kv[k] === userId) { delete kv[k]; ended++; } });
  return { kv: kv, userSets: userSets, ended: ended };
}

